hooks.command:
fp=$(jq -r '.tool_input.file_path // empty')
case "$fp" in
  *src/sfx/roles.ts|*src/sfx/config.ts) ;;
  *) exit 0 ;;
esac
git rev-parse --show-toplevel >/dev/null 2>&1 || exit 0
roles_old=$(git show HEAD:src/sfx/roles.ts 2>/dev/null) || exit 0
ROLES_OLD="$roles_old" node -e "
const fs = require('fs');
function usedSounds(src) {
  const used = new Set();
  const arrays = {};
  for (const m of src.matchAll(/const (\w+): SoundKey\[\] = \[([^\]]*)\]/g)) {
    arrays[m[1]] = [...m[2].matchAll(/'([^']+)'/g)].map(x => x[1]);
  }
  for (const m of src.matchAll(/sound:\s*([^,}\n]+)/g)) {
    const val = m[1].trim();
    if (val.startsWith('[') || val.startsWith(String.fromCharCode(39))) {
      for (const s of val.matchAll(/'([^']+)'/g)) used.add(s[1]);
    } else if (arrays[val]) {
      arrays[val].forEach(s => used.add(s));
    }
  }
  return used;
}
function declaredSounds(src) {
  const m = src.match(/export const SOUNDS = \{([\s\S]*?)\n\} satisfies/);
  if (!m) return new Set();
  return new Set([...m[1].matchAll(/^\s*(\w+):/gm)].map(x => x[1]));
}
const rolesOld = process.env.ROLES_OLD;
const rolesNew = fs.readFileSync('src/sfx/roles.ts', 'utf8');
const configNew = fs.readFileSync('src/sfx/config.ts', 'utf8');
const oldUsed = usedSounds(rolesOld);
const newUsed = usedSounds(rolesNew);
const newDeclared = declaredSounds(configNew);
const newlyOrphaned = [...oldUsed].filter(k => !newUsed.has(k) && newDeclared.has(k));
if (newlyOrphaned.length) {
  console.error('This edit stops any role from referencing ' + newlyOrphaned.join(', ') + ', but src/sfx/config.ts still declares it in SOUNDS -- that sound now plays for nothing. Give it a role, point the reassigned role somewhere new instead, or delete it from SOUNDS to retire it on purpose.');
  process.exit(2);
}
"
